function SET(k,v){return {type:'SET_VARIABLE',variableId:V[k].id,variableValue:{type:typeof v==='boolean'?'BOOLEAN':typeof v==='number'?'FLOAT':'STRING',resolvedType:typeof v==='boolean'?'BOOLEAN':typeof v==='number'?'FLOAT':'STRING',value:v}};}
