function owner(n){while(n.parent&&n.parent.type!=='PAGE'&&n.parent.type!=='SECTION')n=n.parent;return n.name;}
async function wire(){const last=new Map();LINKS.forEach(l=>last.set(l.id,l));for(const l of last.values()){const n=await figma.getNodeByIdAsync(l.id);const act=actions(l.dest,l.opts,owner(n));await n.setReactionsAsync([{trigger:l.opts.timeout?{type:'AFTER_TIMEOUT',timeout:l.opts.timeout}:{type:'ON_CLICK'},actions:act}]);}ledger.links=last.size;}
