function lumin(h){const c=rgb(h);const a=[c.r,c.g,c.b].map(v=>v<=.04045?v/12.92:Math.pow((v+.055)/1.055,2.4));return .2126*a[0]+.7152*a[1]+.0722*a[2];}
function contrast(a,b){const x=lumin(a),y=lumin(b);return +(Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
async function audit(){await page.loadAsync();await lib.loadAsync();const all=page.findAll(()=>true).concat(lib.findAll(()=>true));const counts={};const images=[],badText=[],overflows=[],broken=[],fontFamilies=new Set(),sources=new Map();for(const n of all){counts[n.type]=(counts[n.type]||0)+1;if('fills'in n&&Array.isArray(n.fills)&&n.fills.some(p=>p.type==='IMAGE'))images.push(n.id);if(n.type==='TEXT'){fontFamilies.add(n.fontName.family);if(n.width<1||n.height<1)badText.push(n.id);if(n.parent&&['FRAME','COMPONENT'].includes(n.parent.type)&&n.parent.layoutMode!=='NONE'&&n.visible&&n.x+n.width>n.parent.width+1)overflows.push({id:n.id,name:n.characters,parent:n.parent.name,width:n.width,parentWidth:n.parent.width});}if('reactions'in n&&n.reactions.length){let root=n;while(root.parent&&root.parent.type!=='SECTION'&&root.parent.type!=='PAGE')root=root.parent;const arr=sources.get(root.id)||[];const walk=acts=>acts.forEach(a=>{if(a.type==='NODE'){if(a.destinationId)arr.push(a.destinationId);}if(a.type==='CONDITIONAL')a.conditionalBlocks.forEach(b=>walk(b.actions));});n.reactions.forEach(r=>walk(r.actions||[]));sources.set(root.id,arr);}}
 const allFrameIds=new Set(Object.values(FR).map(f=>f.id));for(const [src,dests]of sources)for(const dst of dests)if(!allFrameIds.has(dst))broken.push({src,dst});const ratios={};for(const t of themes)ratios[t]={body:contrast(PALETTES[t].text,PALETTES[t].card).toFixed(2),secondary:contrast(PALETTES[t].secondary,PALETTES[t].card).toFixed(2),muted:contrast(PALETTES[t].muted,PALETTES[t].card).toFixed(2),button:contrast(PALETTES[t].accentText,PALETTES[t].accent).toFixed(2),warning:contrast(PALETTES[t].warning,PALETTES[t].warningBg).toFixed(2)};
 const missingCounterparts=Object.keys(FR).filter(k=>k.startsWith('Light/')&&!FR[k.replace('Light/','Dark/')]);const result={status:'检查完成',fileKey:FILE_KEY,frames:Object.keys(FR).length,perTheme:Object.keys(FR).length/2,components:Object.keys(COMP).length,links:ledger.links,counts,images,badText,textOverflows:overflows,brokenTargets:broken,fontFamilies:[...fontFamilies],contrast:ratios,missingCounterparts,entries:{light:FR['Light/Review'].id,dark:FR['Dark/Review'].id,lightDashboard:FR['Light/Dashboard'].id,darkDashboard:FR['Dark/Dashboard'].id},frameMap:ledger.frames};figma.ui.postMessage(result);return result;}
async function build(){try{figma.ui.postMessage({status:'正在创建组件与浅深外观…'});await init();buildComponents();for(const t of themes){buildCore(t);buildNotifications(t);buildWidgets(t);buildStates(t);}for(const [id,s]of styleBindings){const n=await figma.getNodeByIdAsync(id);if(n){if(s.fill)await n.setFillStyleIdAsync(s.fill);if(s.text)await n.setTextStyleIdAsync(s.text);}}await wire();organize();await audit();}catch(e){figma.ui.postMessage({status:'设计构建中断',error:String(e),stack:e.stack,created:created.length,last:created.slice(-10),frames:Object.fromEntries(Object.entries(FR).map(([k,v])=>[k,v.id]))});}}
figma.showUI(__html__,{width:590,height:460});
figma.ui.onmessage=async m=>{try{if(m.type==='close')figma.closePlugin();if(m.type==='build')await build();if(m.type==='audit'){if(!page){page=figma.root.children.find(p=>p.name==='01 · 可点击原型');lib=figma.root.children.find(p=>p.name==='02 · 组件与规范');await page.loadAsync();await lib.loadAsync();for(const n of page.findAllWithCriteria({types:['FRAME']})){if(/^(Light|Dark)\//.test(n.name)&&n.parent.type==='SECTION')FR[n.name]=n;}ledger.frames=Object.fromEntries(Object.entries(FR).map(([k,n])=>[k,n.id]));ledger.links=page.findAll(n=>'reactions'in n&&n.reactions.length>0).length;}await audit();}if(m.type==='focus'){if(!page)page=figma.root.children.find(p=>p.name==='01 · 可点击原型');await figma.setCurrentPageAsync(page);await page.loadAsync();const target=page.findOne(n=>n.name===m.target);if(target){page.selection=[target];figma.viewport.scrollAndZoomIntoView([target]);figma.ui.postMessage({status:'已定位 '+m.target,id:target.id});}else figma.ui.postMessage({status:'未找到 '+m.target});}}catch(e){figma.ui.postMessage({status:'error',error:String(e),stack:e.stack});}};
